def max_occurrences(s):
    n = len(s)
    count_01 = 0

    # Count the initial occurrences of '01'
    for i in range(n - 1):
        if s[i:i+2] == '01':
            count_01 += 1

    # Try to maximize the number of '01' occurrences
    for i in range(n):
        for j in range(i + 1, n):
            if (i % 2) == (j % 2):  # Both i and j are of the same parity
                s_list = list(s)
                s_list[i], s_list[j] = s_list[j], s_list[i]
                new_s = ''.join(s_list)
                new_count_01 = 0
                for k in range(n - 1):
                    if new_s[k:k+2] == '01':
                        new_count_01 += 1
                count_01 = max(count_01, new_count_01)

    return count_01

# Read input
T = int(input())
